### CoderSelfHostedProvider

```typescript
// src/providers/coder/self-hosted.ts

import { Provider, DeployOptions, Deployment, /* ... */ } from '../../types.js';
import { CoderClient } from './client.js';
import type { CoderSelfHostedConfig, CoderSelfHostedDeployOptions } from '../../types.js';

/**
 * Self-hosted Coder provider
 * Users manage their own Coder server and credentials
 */
export class CoderSelfHostedProvider implements Provider {
  readonly type = 'coder-self-hosted' as const;
  private client: CoderClient;

  constructor(private config: CoderSelfHostedConfig) {
    // Initialize Tier 2 client
    this.client = new CoderClient({
      url: config.url,
      authToken: config.authToken
    });
  }

  async deploy(options: DeployOptions): Promise<Deployment> {
    // Validate required fields for self-hosted
    if (!options.githubToken) {
      throw new Error('githubToken is required for self-hosted Coder deployments');
    }

    // Ensure user exists (creates with password auth if not)
    await this.client.ensureUserWithPassword({
      username: this.config.username,
      password: this.config.password
    });

    // Prepare template parameters
    const templateParams = {
      // Git configuration
      git_repo_url: `${options.git.owner}/${options.git.repo}`,
      git_branch: options.git.branch || 'main',
      github_token: options.githubToken,

      // User secrets (passed as JSON string to template)
      user_secrets: JSON.stringify(options.secrets || {}),

      // Compute resources
      cpu_cores: options.deployment?.cpuCores || '4',
      memory_gb: options.deployment?.memoryGb || '16',
      disk_size_gb: options.deployment?.diskSizeGb || '50',

      // Server configuration
      server_port: String(options.server.port || 3000),
      idle_timeout_min: String(options.server.idleTimeout || 60),
      ttl_hours: String(options.server.keepAliveHours || 72),

      // Agent installation
      agents: (options.agents || ['claude']).join(','),
      sudocode_version: options.sudocodeVersion || 'latest',
    };

    // Call Tier 2 to create workspace under user's account
    const workspace = await this.client.createWorkspace({
      username: this.config.username,
      template: options.template || 'sudocode-workspace-v0',
      parameters: templateParams
    });

    // Map to sudopod Deployment object
    return this.mapWorkspaceToDeployment(workspace, options);
  }

  async stop(name: string): Promise<void> {
    await this.client.deleteWorkspace(name);
  }

  async getStatus(name: string): Promise<DeploymentStatus> {
    const workspace = await this.client.getWorkspace(name);
    return this.mapWorkspaceStatus(workspace.status);
  }

  async list(filters?: ListFilters): Promise<Deployment[]> {
    const workspaces = await this.client.listWorkspaces();
    return workspaces.map(ws => this.mapWorkspaceToDeployment(ws, {} as DeployOptions));
    // TODO: Apply filters
  }

  async getUrls(name: string): Promise<DeploymentUrls> {
    const workspace = await this.client.getWorkspace(name);
    return {
      workspace: workspace.url,
      sudocode: `${workspace.url}/port/${workspace.sudocodePort}`,
      ssh: `coder ssh ${name}`
    };
  }

  private mapWorkspaceToDeployment(workspace: any, options: DeployOptions): Deployment {
    // Implementation details...
  }

  private mapWorkspaceStatus(status: string): DeploymentStatus {
    // Implementation details...
  }
}
