## Tier 2: Core Coder Library

### CoderClient

```typescript
// src/providers/coder/client.ts

/**
 * Core Coder client implementation (Tier 2)
 * Shared by CoderSelfHostedProvider and sudocode-hub backend
 */
export class CoderClient {
  private baseUrl: string;
  private authToken: string;

  constructor(config: { url: string; authToken: string }) {
    this.baseUrl = config.url;
    this.authToken = config.authToken;
  }

  // =========================================================================
  // User Management
  // =========================================================================

  /**
   * Create or get a user with password authentication
   * Used by self-hosted deployments
   */
  async ensureUserWithPassword(options: {
    username: string;
    password: string;
    email?: string;
  }): Promise<CoderUser> {
    // Check if user exists
    const existing = await this.getUser(options.username).catch(() => null);
    if (existing) {
      return existing;
    }

    // Create user with password auth
    const response = await fetch(`${this.baseUrl}/api/v2/users`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${this.authToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        username: options.username,
        password: options.password,
        email: options.email || `${options.username}@local`,
        login_type: 'password'
      })
    });

    if (!response.ok) {
      throw new Error(`Failed to create user: ${response.statusText}`);
    }

    return await response.json();
  }

  /**
   * Create or get a user with OIDC authentication
   * Used by sudocode-hub deployments
   */
  async ensureUserWithOIDC(options: {
    email: string;
  }): Promise<CoderUser> {
    // Derive username from email (before @)
    const username = options.email.split('@')[0].replace(/[^a-zA-Z0-9]/g, '-');

    // Check if user exists
    const existing = await this.getUser(username).catch(() => null);
    if (existing) {
      return existing;
    }

    // Create user with OIDC auth (no password)
    const response = await fetch(`${this.baseUrl}/api/v2/users`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${this.authToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        username: username,
        email: options.email,
        login_type: 'oidc'
      })
    });

    if (!response.ok) {
      throw new Error(`Failed to create user: ${response.statusText}`);
    }

    return await response.json();
  }

  /**
   * Get user by username
   */
  async getUser(username: string): Promise<CoderUser> {
    const response = await fetch(`${this.baseUrl}/api/v2/users/${username}`, {
      headers: {
        'Authorization': `Bearer ${this.authToken}`
      }
    });

    if (!response.ok) {
      throw new Error(`Failed to get user: ${response.statusText}`);
    }

    return await response.json();
  }

  // =========================================================================
  // Workspace Management
  // =========================================================================

  /**
   * Create a new Coder workspace for a specific user
   */
  async createWorkspace(options: {
    username: string;
    template: string;
    parameters: Record<string, string>;
  }): Promise<CoderWorkspace> {
    const response = await fetch(`${this.baseUrl}/api/v2/users/${options.username}/workspaces`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${this.authToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        template_name: options.template,
        parameters: options.parameters
      })
    });

    if (!response.ok) {
      throw new Error(`Failed to create workspace: ${response.statusText}`);
    }

    return await response.json();
  }

  /**
   * Delete a workspace
   */
  async deleteWorkspace(workspaceId: string): Promise<void> {
    const response = await fetch(`${this.baseUrl}/api/v2/workspaces/${workspaceId}`, {
      method: 'DELETE',
      headers: {
        'Authorization': `Bearer ${this.authToken}`
      }
    });

    if (!response.ok) {
      throw new Error(`Failed to delete workspace: ${response.statusText}`);
    }
  }

  /**
   * Get workspace details
   */
  async getWorkspace(workspaceId: string): Promise<CoderWorkspace> {
    const response = await fetch(`${this.baseUrl}/api/v2/workspaces/${workspaceId}`, {
      headers: {
        'Authorization': `Bearer ${this.authToken}`
      }
    });

    if (!response.ok) {
      throw new Error(`Failed to get workspace: ${response.statusText}`);
    }

    return await response.json();
  }

  /**
   * List all workspaces
   */
  async listWorkspaces(): Promise<CoderWorkspace[]> {
    const response = await fetch(`${this.baseUrl}/api/v2/workspaces`, {
      headers: {
        'Authorization': `Bearer ${this.authToken}`
      }
    });

    if (!response.ok) {
      throw new Error(`Failed to list workspaces: ${response.statusText}`);
    }

    return await response.json();
  }
}

/**
 * Coder user representation
 */
interface CoderUser {
  id: string;
  username: string;
  email: string;
  login_type: 'password' | 'oidc';
  created_at: string;
}

/**
 * Coder workspace representation
 */
interface CoderWorkspace {
  id: string;
  name: string;
  owner_name: string;
  template_name: string;
  status: 'pending' | 'starting' | 'running' | 'stopping' | 'stopped' | 'failed';
  url: string;
  created_at: string;
  // ... other Coder API fields
}
```

## Coder Template Design

### Template Location

The `sudocode-workspace-v0` template lives in the `coder-infra` repository alongside the Coder deployment infrastructure. This template is packaged with our Coder deployment.

### Workspace Lifecycle

Coder handles workspace stop/start by running `terraform apply` on each transition:
- **Stop**: Resources with `count = data.coder_workspace.me.start_count` are destroyed
- **Start**: Resources are recreated, and `coder_script` with `run_on_start = true` executes

This means:
- **Containers are ephemeral** - recreated on each start
- **Volumes are persistent** - survive stop/start cycles
- **Startup scripts run on every start** - must handle both cold and warm starts

### Cold vs Warm Start Detection

Since volumes persist but containers don't, the startup script detects the start type:
- **Cold start**: No repo exists on the persistent volume → clone the repo
- **Warm start**: Repo already exists → pull latest changes

### Template: sudocode-workspace-v0

```hcl
# coder-infra/templates/sudocode-workspace-v0/main.tf

terraform {
  required_providers {
    coder = {
      source  = "coder/coder"
      version = "~> 0.12"
    }
    docker = {
      source  = "kreuzwerker/docker"
      version = "~> 3.0"
    }
  }
}

# ============================================================================
# PARAMETERS (from sudopod DeployOptions)
# ============================================================================

variable "git_repo_url" {
  type        = string
  description = "Git repository in owner/repo format (e.g., 'myorg/myrepo')"
}

variable "git_branch" {
  type        = string
  description = "Git branch to checkout"
  default     = "main"
}

variable "github_token" {
  type        = string
  description = "GitHub token for cloning private repositories"
  sensitive   = true
}

variable "user_secrets" {
  type        = string
  description = "User-defined secrets as JSON string"
  sensitive   = true
  default     = "{}"
}

variable "cpu_cores" {
  type        = string
  description = "Number of CPU cores"
  default     = "4"
}

variable "memory_gb" {
  type        = string
  description = "Memory in GB"
  default     = "16"
}

variable "disk_size_gb" {
  type        = string
  description = "Disk size in GB"
  default     = "50"
}

variable "server_port" {
  type        = string
  description = "Sudocode server port"
  default     = "3000"
}

variable "idle_timeout_min" {
  type        = string
  description = "Idle timeout in minutes"
  default     = "60"
}

variable "ttl_hours" {
  type        = string
  description = "TTL in hours"
  default     = "72"
}

variable "agents" {
  type        = string
  description = "Comma-separated list of agents to install (e.g., 'claude,codex')"
  default     = "claude"
}

variable "sudocode_version" {
  type        = string
  description = "Sudocode version to install (default: latest)"
  default     = "latest"
}

# ============================================================================
# LOCALS
# ============================================================================

locals {
  # Parse user secrets from JSON
  secrets = jsondecode(var.user_secrets)

  # Extract repo name from owner/repo format
  git_repo_name = element(split("/", var.git_repo_url), 1)

  # Workspace directory on persistent volume
  workspace_dir = "/workspace/${local.git_repo_name}"

  # Parse agents list
  agents_list = split(",", var.agents)
}

# ============================================================================
# PERSISTENT VOLUMES
# ============================================================================

# Persistent volume for workspace files (survives stop/start)
resource "docker_volume" "workspace" {
  name = "coder-workspace-${data.coder_workspace.me.id}"

  lifecycle {
    ignore_changes = all
  }
}

# Persistent volume for sudocode logs and state
resource "docker_volume" "sudocode" {
  name = "coder-sudocode-${data.coder_workspace.me.id}"

  lifecycle {
    ignore_changes = all
  }
}

# ============================================================================
# WORKSPACE
# ============================================================================

data "coder_workspace" "me" {}
data "coder_workspace_owner" "me" {}

resource "coder_agent" "main" {
  os   = "linux"
  arch = "amd64"

  # Standard environment variables
  env = {
    GIT_REPO       = var.git_repo_url
    GIT_BRANCH     = var.git_branch
    SUDOCODE_PORT  = var.server_port
    WORKSPACE_DIR  = local.workspace_dir
  }
}

# Startup script runs on every workspace start (handles cold and warm starts)
resource "coder_script" "startup" {
  agent_id     = coder_agent.main.id
  display_name = "Workspace Setup"
  icon         = "/icon/coder.svg"
  run_on_start = true

  script = <<-EOT
    #!/bin/bash
    set -e

    WORKSPACE_DIR="${local.workspace_dir}"
    LOG_DIR="/sudocode/logs"
    mkdir -p "$LOG_DIR"

    echo "=== Workspace startup at $(date) ===" >> "$LOG_DIR/startup.log"

    # ----------------------------------------------------------------
    # STEP 1: Clone or update repository (cold vs warm start)
    # ----------------------------------------------------------------
    if [ -d "$WORKSPACE_DIR/.git" ]; then
      echo "Warm start: repo exists, pulling latest..."
      cd "$WORKSPACE_DIR"
      git fetch origin
      git checkout ${var.git_branch}
      git pull origin ${var.git_branch} || true
    else
      echo "Cold start: cloning repo..."
      mkdir -p "$(dirname "$WORKSPACE_DIR")"
      git clone https://x-access-token:${var.github_token}@github.com/${var.git_repo_url}.git "$WORKSPACE_DIR"
      cd "$WORKSPACE_DIR"
      git checkout ${var.git_branch}
    fi

    # ----------------------------------------------------------------
    # STEP 2: Start or rebuild devcontainer
    # ----------------------------------------------------------------
    CONTAINER_NAME="devcontainer-${data.coder_workspace.me.id}"

    if docker ps -a --format '{{.Names}}' | grep -q "^$CONTAINER_NAME$"; then
      echo "Devcontainer exists, starting..."
      docker start "$CONTAINER_NAME"
    else
      echo "Building devcontainer..."
      if [ -f "$WORKSPACE_DIR/.devcontainer/devcontainer.json" ]; then
        devcontainer up \
          --workspace-folder "$WORKSPACE_DIR" \
          --container-name "$CONTAINER_NAME" \
          --mount "type=volume,source=coder-sudocode-${data.coder_workspace.me.id},target=/sudocode"
      else
        echo "No devcontainer.json, using default sudocode image..."
        docker run -d \
          --name "$CONTAINER_NAME" \
          -v "coder-workspace-${data.coder_workspace.me.id}:/workspace" \
          -v "coder-sudocode-${data.coder_workspace.me.id}:/sudocode" \
          -p ${var.server_port}:${var.server_port} \
          sudocode/default-devcontainer:latest
      fi
    fi

    # ----------------------------------------------------------------
    # STEP 3: Install sudocode inside devcontainer
    # ----------------------------------------------------------------
    echo "Installing sudocode@${var.sudocode_version}..."
    SUDOCODE_VERSION="${var.sudocode_version}"
    if [ "$SUDOCODE_VERSION" = "latest" ]; then
      devcontainer exec --workspace-folder "$WORKSPACE_DIR" npm install -g sudocode
    else
      devcontainer exec --workspace-folder "$WORKSPACE_DIR" npm install -g sudocode@$SUDOCODE_VERSION
    fi

    # ----------------------------------------------------------------
    # STEP 4: Install agents inside devcontainer
    # ----------------------------------------------------------------
    %{ for agent in local.agents_list ~}
    echo "Installing agent: ${agent}..."
    case "${agent}" in
      claude)
        devcontainer exec --workspace-folder "$WORKSPACE_DIR" bash -c \
          'command -v claude || curl -fsSL https://claude.ai/install.sh | bash'
        ;;
      # Add more agents here as needed:
      # codex)
      #   devcontainer exec --workspace-folder "$WORKSPACE_DIR" bash -c \
      #     'command -v codex || <install command>'
      #   ;;
      *)
        echo "Unknown agent: ${agent}, skipping..."
        ;;
    esac
    %{ endfor ~}

    # ----------------------------------------------------------------
    # STEP 5: Inject user secrets as environment variables
    # ----------------------------------------------------------------
    %{ for key, value in local.secrets ~}
    devcontainer exec --workspace-folder "$WORKSPACE_DIR" bash -c \
      'echo "export ${key}=\"${value}\"" >> ~/.bashrc'
    %{ endfor ~}

    # ----------------------------------------------------------------
    # STEP 6: Start sudocode server with auto-restart
    # ----------------------------------------------------------------
    echo "Starting sudocode server on port ${var.server_port}..."

    # Kill any existing sudocode server
    devcontainer exec --workspace-folder "$WORKSPACE_DIR" bash -c \
      'pkill -f "sudocode server" || true'

    # Start server with restart loop (runs in background)
    devcontainer exec --workspace-folder "$WORKSPACE_DIR" bash -c "
      while true; do
        echo \"Starting sudocode server at \$(date)\" >> /sudocode/logs/server.log
        sudocode server --port ${var.server_port} >> /sudocode/logs/server.log 2>&1
        echo \"Sudocode server exited, restarting in 5s...\" >> /sudocode/logs/server.log
        sleep 5
      done &
    "

    echo "=== Workspace ready at $(date) ===" >> "$LOG_DIR/startup.log"
    echo "Workspace ready!"
  EOT
}

# Docker container for workspace (ephemeral - recreated on each start)
resource "docker_container" "workspace" {
  count = data.coder_workspace.me.start_count

  image = "codercom/enterprise-base:ubuntu"
  name  = "coder-${data.coder_workspace.me.id}"

  # Resource limits
  cpu_shares = tonumber(var.cpu_cores) * 1024
  memory     = tonumber(var.memory_gb) * 1024 * 1024 * 1024

  # Mount persistent volumes
  volumes {
    volume_name    = docker_volume.workspace.name
    container_path = "/workspace"
  }

  volumes {
    volume_name    = docker_volume.sudocode.name
    container_path = "/sudocode"
  }

  # Expose sudocode port
  ports {
    internal = tonumber(var.server_port)
    external = tonumber(var.server_port)
  }
}
```

### Volume Strategy

Two persistent volumes survive workspace stop/start cycles:

1. **`/workspace`** - Contains cloned repositories
   - Cold start: repo is cloned here
   - Warm start: repo already exists, just pull latest

2. **`/sudocode`** - Contains logs and sudocode state
   - `logs/server.log` - Sudocode server logs
   - `logs/startup.log` - Workspace startup logs

The container itself is ephemeral (uses `start_count`), but data persists in volumes.

