### Wait for Workspace Ready

```typescript
async waitForWorkspaceReady(
  workspaceId: string,
  timeoutMs: number = 300000 // 5 minutes
): Promise<CoderWorkspace> {
  const startTime = Date.now();
  const pollInterval = 2000; // 2 seconds

  while (Date.now() - startTime < timeoutMs) {
    const workspace = await this.getWorkspace(workspaceId);
    const buildStatus = workspace.latest_build.status;
    const jobStatus = workspace.latest_build.job.status;

    // Workspace is ready when build is running and job succeeded
    if (buildStatus === 'running' && jobStatus === 'succeeded') {
      return workspace;
    }

    // Terminal failure states
    if (buildStatus === 'failed' || buildStatus === 'canceled') {
      throw new CoderWorkspaceError(
        `Workspace build ${buildStatus}`,
        workspace
      );
    }

    if (jobStatus === 'failed' || jobStatus === 'canceled') {
      throw new CoderWorkspaceError(
        `Workspace provisioner job ${jobStatus}`,
        workspace
      );
    }

    await this.sleep(pollInterval);
  }

  throw new CoderTimeoutError(
    `Workspace did not become ready within ${timeoutMs}ms`
  );
}

private sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}
```

## Error Handling

```typescript
export class CoderAPIError extends Error {
  constructor(
    public readonly status: number,
    message: string,
    public readonly detail?: string,
    public readonly validations?: Array<{field: string, error: string}>
  ) {
    const fullMessage = detail 
      ? `Coder API error (${status}): ${message} - ${detail}`
      : `Coder API error (${status}): ${message}`;
    super(fullMessage);
    this.name = 'CoderAPIError';
  }

  isConflict(): boolean {
    return this.status === 409;
  }

  isNotFound(): boolean {
    return this.status === 404;
  }
}

export class CoderWorkspaceError extends Error {
  constructor(
    message: string,
    public readonly workspace: CoderWorkspace
  ) {
    super(message);
    this.name = 'CoderWorkspaceError';
  }
}

export class CoderTimeoutError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CoderTimeoutError';
  }
}
