```typescript
/**
 * Standardized HTTP server that wraps any ProviderClient.
 * Used by infra repos to expose identical APIs regardless of provider.
 */
export class InfraServer {
  constructor(private client: ProviderClient) {}

  /**
   * Start the HTTP server
   */
  listen(port: number): void {
    // POST /deployments
    // DELETE /deployments/:id
    // GET /deployments/:id
    // GET /deployments
    // POST /deployments/:id/pause (if client.pause exists)
    // POST /deployments/:id/resume (if client.resume exists)
  }
}
