### CodespacesProvider (Direct, no InfraServer)

Codespaces is special - it uses gh CLI directly and doesn't need an infra server.

```typescript
export class CodespacesProvider implements Provider {
  readonly type = 'codespaces';

  async deploy(options: DeployOptions): Promise<Deployment> {
    // Uses gh CLI directly
    // No InfraServer involved
  }
}
```

### CoderSelfHostedProvider (Uses CoderClient directly)

For users running their own Coder server.

```typescript
export class CoderSelfHostedProvider implements Provider {
  readonly type = 'coder-self-hosted';
  private client: CoderClient;

  constructor(config: CoderSelfHostedConfig) {
    this.client = new CoderClient({
      url: config.url,
      authToken: config.authToken,
    });
  }

  async deploy(options: DeployOptions): Promise<Deployment> {
    return this.client.deploy(options);
  }
}
```

### HubProvider (Calls hub HTTP API)

For users going through sudocode-hub to our managed infrastructure.

```typescript
export class HubProvider implements Provider {
  readonly type = 'hub';

  constructor(private config: HubConfig) {}

  async deploy(options: DeployOptions): Promise<Deployment> {
    // Calls sudocode-hub HTTP API
    // Hub forwards to appropriate infra server
    // Does NOT include githubToken or secrets - hub injects those
    const response = await fetch(`${this.config.hubUrl}/deployments`, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${this.config.authToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        git: options.git,
        server: options.server,
        resources: options.resources,
        agents: options.agents,
        sudocodeVersion: options.sudocodeVersion,
        // NO githubToken, NO secrets - hub provides these
      }),
    });
    return response.json();
  }
}
```

